class Solution {
public:
    int maxProfit(vector<int>& prices, int cooldown, vector<int>& costs) {
        int n = prices.size();
        vector<long long> dp(n + 1, 0);
        for (int j = 0; j < n; ++j) {
            dp[j + 1] = max(dp[j + 1], dp[j]);
            for (int i = 0; i < j; ++i) {
                int previous = max(0, i - cooldown);
                long long profit = dp[previous] + prices[j] - prices[i] - costs[j - i];
                dp[j + 1] = max(dp[j + 1], profit);
            }
        }
        return (int)dp[n];
    }
};
